add("ex6", ("किन्हीं दो प्रावधानों का ज़िक्र करें जो भारत को धर्मनिरपेक्ष देश बनाते हैं।", "ભારતને બિનસાંપ્રદાયિક દેશ બનાવતી કોઈ પણ બે બંધારણીય જોગવાઈઓ જણાવો."),
    {0: ("भारतीय राज्य का कोई आधिकारिक धर्म नहीं है; और संविधान हर किसी को किसी भी धर्म को मानने, उसका आचरण और प्रचार करने, या कोई धर्म न मानने की आज़ादी देता है।", "ભારતીય રાજ્યનો કોઈ સત્તાવાર ધર્મ નથી; અને બંધારણ દરેકને કોઈ પણ ધર્મ પાળવા, આચરવા અને પ્રચાર કરવાની, કે કોઈ ધર્મ ન પાળવાની સ્વતંત્રતા આપે છે."),
     1: ("संविधान धर्म के आधार पर भेदभाव का निषेध करता है, और धार्मिक समुदायों के अंदर समानता के लिए शासन को दख़ल देने देता है, जैसे छुआछूत पर रोक।", "બંધારણ ધર્મના આધારે ભેદભાવ પર પ્રતિબંધ મૂકે છે, અને ધાર્મિક સમુદાયોમાં સમાનતા માટે રાજ્યને દખલ કરવા દે છે, જેમ કે અસ્પૃશ્યતા પર પ્રતિબંધ.")})
mc("ex7", ("जब हम लैंगिक विभाजन की बात करते हैं तो हमारा अभिप्राय होता है:", "જ્યારે આપણે લૈંગિક વિભાજનની વાત કરીએ, ત્યારે સામાન્ય રીતે તેનો અર્થ થાય છે:"), ("लैंगिक विभाजन सामाजिक अपेक्षाओं और रूढ़ छवियों पर आधारित है।", "લૈંગિક વિભાજન સામાજિક અપેક્ષાઓ અને રૂઢ માન્યતાઓ પર આધારિત છે."),
   {"Unequal roles assigned by the society to men and women": (("समाज द्वारा स्त्री और पुरुष को दी गई असमान भूमिकाएँ", "સમાજે સ્ત્રી અને પુરુષને સોંપેલી અસમાન ભૂમિકાઓ"), OK), "Biological difference between men and women": (("स्त्री और पुरुष के बीच जैविक अंतर", "સ્ત્રી અને પુરુષ વચ્ચેનો જૈવિક તફાવત"), ("लैंगिक विभाजन सामाजिक है, जैविक नहीं।", "લૈંગિક વિભાજન સામાજિક છે, જૈવિક નહિ.")),
    "Unequal child sex ratio": (("बाल लिंग अनुपात में असमानता", "બાળ જાતિ પ્રમાણમાં અસમાનતા"), ("यह लैंगिक विभाजन का एक परिणाम है।", "આ લૈંગિક વિભાજનનું એક પરિણામ છે.")), "Absence of voting rights for women in democracies": (("लोकतांत्रिक व्यवस्थाओं में महिलाओं को मताधिकार न मिलना", "લોકશાહીમાં સ્ત્રીઓને મતાધિકાર ન મળવો"), ("लोकतंत्रों में महिलाओं को मताधिकार है।", "લોકશાહીમાં સ્ત્રીઓને મતાધિકાર છે."))})
mc("ex8", ("भारत में यहाँ औरतों के लिए आरक्षण की व्यवस्था है (जैसा NCERT अभ्यास में दिया है):", "ભારતમાં સ્ત્રીઓ માટે અહીં બેઠકો અનામત છે (NCERT સ્વાધ્યાય પ્રમાણે):"), ("पंचायतों और नगरपालिकाओं में एक-तिहाई सीटें महिलाओं के लिए आरक्षित हैं।", "પંચાયતો અને નગરપાલિકાઓમાં એક-તૃતીયાંશ બેઠકો સ્ત્રીઓ માટે અનામત છે."),
   {"Panchayati Raj bodies": (("पंचायती राज के निकाय", "પંચાયતી રાજની સંસ્થાઓ"), OK), "Lok Sabha": (("लोकसभा", "લોકસભા"), ("लोकसभा में सीटें आरक्षित करने वाला 2023 का अधिनियम अगली जनगणना और परिसीमन के बाद ही लागू होगा।", "લોકસભામાં બેઠકો અનામત રાખતો 2023નો અધિનિયમ આગામી વસ્તી ગણતરી અને સીમાંકન પછી જ લાગુ થશે.")),
    "State legislative assemblies": (("विधानसभा", "રાજ્ય વિધાનસભાઓ"), ("यहाँ भी आरक्षण अगली जनगणना और परिसीमन का इंतज़ार कर रहा है।", "અહીં પણ અનામત આગામી વસ્તી ગણતરી અને સીમાંકનની રાહ જુએ છે.")), "Cabinets": (("मंत्रिमंडल", "પ્રધાનમંડળ"), ("मंत्रिमंडल में आरक्षण नहीं है।", "પ્રધાનમંડળમાં અનામત નથી."))})
mc("ex9", ("सांप्रदायिक राजनीति इस धारणा पर आधारित है कि: (क) एक धर्म दूसरों से श्रेष्ठ है। (ख) विभिन्न धर्मों के लोग समान नागरिक के रूप में ख़ुशी-ख़ुशी साथ रहते हैं। (ग) एक धर्म के अनुयायी एक समुदाय बनाते हैं। (घ) एक धार्मिक समूह का प्रभुत्व बाक़ी सभी धर्मों पर क़ायम करने में शासन की शक्ति का प्रयोग नहीं किया जा सकता। कौन-से कथन सही हैं?", "કોમવાદી રાજકારણ એ માન્યતા પર આધારિત છે કે: (A) એક ધર્મ બીજા કરતાં ચડિયાતો છે. (B) જુદા જુદા ધર્મના લોકો સમાન નાગરિક તરીકે આનંદથી સાથે રહી શકે. (C) એક ધર્મના અનુયાયીઓ એક સમુદાય બનાવે છે. (D) એક ધાર્મિક જૂથનું બીજાં પર વર્ચસ્વ સ્થાપવા રાજ્યસત્તાનો ઉપયોગ કરી શકાય નહિ. કયાં વિધાનો સાચાં છે?"),
   ("सांप्रदायिक राजनीति एक धर्म की श्रेष्ठता में विश्वास करती है और उसके अनुयायियों को एक समुदाय मानती है।", "કોમવાદી રાજકારણ એક ધર્મની શ્રેષ્ઠતામાં માને છે અને તેના અનુયાયીઓને એક સમુદાય માને છે."),
   {"A and C": (("क और ग", "A અને C"), OK), "A, B, C and D": (("क, ख, ग और घ", "A, B, C અને D"), ("ख और घ धर्मनिरपेक्ष विचार हैं।", "B અને D બિનસાંપ્રદાયિક વિચારો છે.")),
    "A, B and D": (("क, ख और घ", "A, B અને D"), ("ख और घ धर्मनिरपेक्ष विचार हैं।", "B અને D બિનસાંપ્રદાયિક વિચારો છે.")), "B and D": (("ख और घ", "B અને D"), ("ये सांप्रदायिक राजनीति के उलट हैं।", "આ કોમવાદી રાજકારણથી ઊલટા છે."))})
mc("ex10", ("भारतीय संविधान के बारे में इनमें से कौन-सा कथन ग़लत है? यह:", "ભારતના બંધારણ વિશે આમાંથી કયું વિધાન ખોટું છે? તે:"), ("भारत का कोई आधिकारिक धर्म नहीं है।", "ભારતનો કોઈ સત્તાવાર ધર્મ નથી."),
   {"gives official status to one religion": (("एक धर्म को राजकीय धर्म बताता है", "એક ધર્મને સત્તાવાર દરજ્જો આપે છે"), OK), "prohibits discrimination on grounds of religion": (("धर्म के आधार पर भेदभाव की मनाही करता है", "ધર્મના આધારે ભેદભાવ પર પ્રતિબંધ મૂકે છે"), ("यह सही है।", "આ સાચું છે.")),
    "provides to all individuals freedom to profess any religion": (("सभी लोगों को कोई भी धर्म मानने की आज़ादी देता है", "બધી વ્યક્તિઓને કોઈ પણ ધર્મ પાળવાની સ્વતંત્રતા આપે છે"), ("यह सही है।", "આ સાચું છે.")),
    "ensures equality of citizens within religious communities": (("किसी धार्मिक समुदाय में सभी नागरिकों को बराबरी का अधिकार देता है", "ધાર્મિક સમુદાયોમાં નાગરિકોની સમાનતા સુનિશ્ચિત કરે છે"), ("यह सही है।", "આ સાચું છે."))})
mc("ex11", ("________ पर आधारित विभाजन सिर्फ़ भारत में है।", "________ પર આધારિત સામાજિક વિભાજન ફક્ત ભારતમાં છે."), ("जाति आधारित विभाजन सिर्फ़ भारत में है।", "જ્ઞાતિ આધારિત વિભાજન ફક્ત ભારતમાં છે."),
   {"caste": (("जाति", "જ્ઞાતિ"), OK), "gender": (("लिंग", "લિંગ"), ("लैंगिक विभाजन हर जगह है।", "લૈંગિક વિભાજન બધે છે.")), "religion": (("धर्म", "ધર્મ"), ("धार्मिक विभाजन कई देशों में है।", "ધાર્મિક વિભાજન ઘણા દેશોમાં છે.")), "language": (("भाषा", "ભાષા"), ("भाषायी विभाजन कई देशों में है।", "ભાષાકીય વિભાજન ઘણા દેશોમાં છે."))})
mc("ex12", ("सुमेलित कीजिए: (1) अधिकारों और अवसरों के मामले में स्त्री और पुरुष की बराबरी मानने वाला व्यक्ति, (2) धर्म को समुदाय का मुख्य आधार मानने वाला व्यक्ति, (3) जाति को समुदाय का मुख्य आधार मानने वाला व्यक्ति, (4) व्यक्तियों के बीच धार्मिक आस्था के आधार पर भेदभाव न करने वाला व्यक्ति, इनका मेल (क) सांप्रदायिक, (ख) नारीवादी, (ग) धर्मनिरपेक्ष, (घ) जातिवादी से करें। 1, 2, 3, 4 का सही क्रम है:", "જોડકાં જોડો: (1) સ્ત્રી અને પુરુષના સમાન અધિકારો અને તકોમાં માનનાર વ્યક્તિ, (2) ધર્મને સમુદાયનો મુખ્ય આધાર માનનાર વ્યક્તિ, (3) જ્ઞાતિને સમુદાયનો મુખ્ય આધાર માનનાર વ્યક્તિ, (4) ધાર્મિક માન્યતાના આધારે ભેદભાવ ન કરનાર વ્યક્તિ, તેને (A) કોમવાદી, (B) નારીવાદી, (C) બિનસાંપ્રદાયિક, (D) જ્ઞાતિવાદી સાથે જોડો. 1, 2, 3, 4નો સાચો ક્રમ છે:"),
   ("1-ख, 2-क, 3-घ, 4-ग।", "1-B, 2-A, 3-D, 4-C."),
   {"B A D C": (("ख क घ ग", "B A D C"), OK), "B C A D": (("ख ग क घ", "B C A D"), ("2 सांप्रदायिक है, धर्मनिरपेक्ष नहीं।", "2 કોમવાદી છે, બિનસાંપ્રદાયિક નહિ.")),
    "D C A B": (("घ ग क ख", "D C A B"), ("1 नारीवादी है।", "1 નારીવાદી છે.")), "C D B A": (("ग घ ख क", "C D B A"), ("1 नारीवादी और 4 धर्मनिरपेक्ष है।", "1 નારીવાદી અને 4 બિનસાંપ્રદાયિક છે."))})

