mc("mcq30", ("लैंगिक विभाजन के बारे में कौन-सा कथन दिखाता है कि इसे राजनीति में व्यक्त होना चाहिए?", "લૈંગિક વિભાજન વિશે કયું વિધાન બતાવે છે કે તે રાજકારણમાં વ્યક્ત થવું જોઈએ?"), ("जहाँ महिलाओं की भागीदारी बढ़ी, वहाँ सार्वजनिक जीवन में उनकी भूमिका सुधरी।", "જ્યાં સ્ત્રીઓની ભાગીદારી વધી, ત્યાં જાહેર જીવનમાં તેમની ભૂમિકા સુધરી."),
   {"Disadvantaged groups benefit when social divisions become a political issue": (("जब सामाजिक विभाजन राजनीतिक मुद्दा बनता है, तो वंचित समूहों को लाभ होता है", "જ્યારે સામાજિક વિભાજન રાજકીય મુદ્દો બને, ત્યારે વંચિત જૂથોને લાભ થાય છે"), OK), "Women should stay out of politics": (("महिलाओं को राजनीति से दूर रहना चाहिए", "સ્ત્રીઓએ રાજકારણથી દૂર રહેવું જોઈએ"), ("यह पितृसत्तात्मक सोच है।", "આ પિતૃસત્તાક વિચાર છે.")),
    "Gender roles are natural and fixed": (("लैंगिक भूमिकाएँ प्राकृतिक और तय हैं", "લૈંગિક ભૂમિકાઓ કુદરતી અને નક્કી છે"), ("वे सामाजिक हैं और बदल सकती हैं।", "તે સામાજિક છે અને બદલાઈ શકે.")), "Only men's interests matter in politics": (("राजनीति में केवल पुरुषों के हित मायने रखते हैं", "રાજકારણમાં ફક્ત પુરુષોનાં હિતો મહત્ત્વનાં છે"), ("महिलाएँ मानवता का आधा हिस्सा हैं।", "સ્ત્રીઓ માનવજાતનો અડધો ભાગ છે."))})
